          '1/[2(%(CT).0f&nbsp;pF&times;%(RT).0f&nbsp;k&Omega; + '
          '%(Ts).2f&nbsp;&micro;s)] &nbsp;=&nbsp; 1/(2&times;%(tot).3f'
          '&nbsp;&micro;s) &nbsp;=&nbsp; <b>%(fMin).2f&nbsp;kHz</b> 다. '
